						if readErr != nil {
							if os.IsNotExist(readErr) {
								diags = diags.Append(fmt.Errorf("There is no configuration directory at %s", frame.path))
							} else {
								diags = diags.Append(fmt.Errorf("Cannot read directory %s", frame.path))
							}
							frames = frames[:len(frames)-1]
